-- Deterministic local/test fixture for the four Phase 1 competency cases.
-- This file contains data only. It is intentionally not included by seed.sql.

begin;

set local lock_timeout = '5s';
set local statement_timeout = '30s';

-- Fail rather than silently duplicate manually entered versions of these cases.
do $$
begin
    if exists (
        select 1
        from entities.entity
        where id in (
            '30000000-0000-4000-8000-000000000001'::uuid,
            '30000000-0000-4000-8000-000000000002'::uuid,
            '30000000-0000-4000-8000-000000000003'::uuid,
            '30000000-0000-4000-8000-000000000004'::uuid,
            '30000000-0000-4000-8000-000000000005'::uuid
        )
        and entity_type <> 'item'
    ) then
        raise exception
            'Phase 1 fixture item UUIDs are already used by non-item entities. Reset the local database before loading fixtures.';
    end if;

    if exists (
        select 1
        from entities.external_identifier
        where (namespace, value) in (
            ('british-museum', 'Oc1869,1005.1'),
            ('british-museum-aoa', '1869,10-5.1'),
            ('museo-delle-civilta', 'MPE 32571'),
            ('kunstkamera', 'МАЭ № 736-205')
        )
        and id not in (
            '70000000-0000-4000-8000-000000000001'::uuid,
            '70000000-0000-4000-8000-000000000002'::uuid,
            '70000000-0000-4000-8000-000000000003'::uuid,
            '70000000-0000-4000-8000-000000000004'::uuid
        )
    ) then
        raise exception
            'Phase 1 fixture identifiers already exist under non-fixture UUIDs. Reset the local database before loading fixtures.';
    end if;
end;
$$;

-- Make the fixture safely repeatable when only these reserved UUIDs exist.
delete from knowledge.claim_evidence
where id >= '60000000-0000-4000-8000-000000000000'::uuid
  and id <  '60000000-0000-4000-8000-000000000100'::uuid;

delete from knowledge.claim
where id >= '50000000-0000-4000-8000-000000000000'::uuid
  and id <  '50000000-0000-4000-8000-000000000100'::uuid;

delete from entities.external_identifier
where id >= '70000000-0000-4000-8000-000000000000'::uuid
  and id <  '70000000-0000-4000-8000-000000000100'::uuid;

delete from entities.item
where id >= '30000000-0000-4000-8000-000000000000'::uuid
  and id <  '30000000-0000-4000-8000-000000000100'::uuid;

delete from entities.agent
where id >= '10000000-0000-4000-8000-000000000000'::uuid
  and id <  '10000000-0000-4000-8000-000000000100'::uuid;

delete from entities.place
where id >= '20000000-0000-4000-8000-000000000000'::uuid
  and id <  '20000000-0000-4000-8000-000000000100'::uuid;

delete from entities.source
where id >= '40000000-0000-4000-8000-000000000000'::uuid
  and id <  '40000000-0000-4000-8000-000000000100'::uuid;

delete from entities.entity
where id in (
    '10000000-0000-4000-8000-000000000001'::uuid,
    '10000000-0000-4000-8000-000000000002'::uuid,
    '10000000-0000-4000-8000-000000000003'::uuid,
    '10000000-0000-4000-8000-000000000004'::uuid,
    '10000000-0000-4000-8000-000000000005'::uuid,
    '10000000-0000-4000-8000-000000000006'::uuid,
    '20000000-0000-4000-8000-000000000001'::uuid,
    '20000000-0000-4000-8000-000000000002'::uuid,
    '20000000-0000-4000-8000-000000000003'::uuid,
    '20000000-0000-4000-8000-000000000004'::uuid,
    '30000000-0000-4000-8000-000000000001'::uuid,
    '30000000-0000-4000-8000-000000000002'::uuid,
    '30000000-0000-4000-8000-000000000003'::uuid,
    '30000000-0000-4000-8000-000000000004'::uuid,
    '30000000-0000-4000-8000-000000000005'::uuid,
    '40000000-0000-4000-8000-000000000001'::uuid,
    '40000000-0000-4000-8000-000000000002'::uuid,
    '40000000-0000-4000-8000-000000000003'::uuid,
    '40000000-0000-4000-8000-000000000004'::uuid,
    '40000000-0000-4000-8000-000000000005'::uuid,
    '40000000-0000-4000-8000-000000000006'::uuid,
    '40000000-0000-4000-8000-000000000007'::uuid
);

